use std::cell::RefCell;
use std::rc::Rc;
use std::collections::HashMap;

type Station = Rc<RefCell<GraphNode>>;

fn copy(station: &Station, copies: &mut HashMap<*const RefCell<GraphNode>, Station>) -> Station {
    if let Some(done) = copies.get(&Rc::as_ptr(station)) {
        return Rc::clone(done);
    }
    // Register the copy *before* copying the neighbours: a track leads back to
    // this station, and the lookup above is what stops that from recursing forever.
    let clone = Rc::new(RefCell::new(GraphNode::new(station.borrow().val)));
    copies.insert(Rc::as_ptr(station), Rc::clone(&clone));
    let neighbors: Vec<Station> = station.borrow().neighbors.iter().map(|n| copy(n, copies)).collect();
    clone.borrow_mut().neighbors = neighbors;
    clone
}

fn copy_map(node: Option<Rc<RefCell<GraphNode>>>) -> Option<Rc<RefCell<GraphNode>>> {
    node.map(|n| copy(&n, &mut HashMap::new()))
}

