from collections import deque


def copy_map(node: "GraphNode | None") -> "GraphNode | None":
    if node is None:
        return None
    copies = {node: GraphNode(node.val)}
    queue = deque([node])
    while queue:
        station = queue.popleft()
        for n in station.neighbors:
            if n not in copies:
                copies[n] = GraphNode(n.val)
                queue.append(n)
            copies[station].neighbors.append(copies[n])
    return copies[node]

code.rust:
use std::cell::RefCell;
use std::rc::Rc;
use std::collections::{HashMap, VecDeque};

fn copy_map(node: Option<Rc<RefCell<GraphNode>>>) -> Option<Rc<RefCell<GraphNode>>> {
    let start = node?;
    let mut copies = HashMap::new();
    copies.insert(Rc::as_ptr(&start), Rc::new(RefCell::new(GraphNode::new(start.borrow().val))));
    let mut queue = VecDeque::from([Rc::clone(&start)]);
    while let Some(station) = queue.pop_front() {
        let clone = Rc::clone(&copies[&Rc::as_ptr(&station)]);
        for n in &station.borrow().neighbors {
            let n_clone = copies.entry(Rc::as_ptr(n)).or_insert_with(|| {
                queue.push_back(Rc::clone(n));
                Rc::new(RefCell::new(GraphNode::new(n.borrow().val)))
            });
            clone.borrow_mut().neighbors.push(Rc::clone(n_clone));
        }
    }
    copies.remove(&Rc::as_ptr(&start))
}
